        nav a { color: #F5E6D3; font-size: 15px; font-weight: 500; padding: 6px 0; border-bottom: 2px solid transparent; transition: all 0.3s; }
        nav a:hover, nav a.active { color: #FFF; border-bottom-color: #E8C96A; }

        .page-hero { background: linear-gradient(135deg, #3D1F1F, #8B2E2E); padding: 60px 40px; text-align: center; }
        .page-hero h1 { color: #FFF; font-size: 36px; margin-bottom: 10px; }
        .page-hero p { color: #F0D9B5; font-size: 16px; }

        .section { padding: 60px 40px; max-width: 1000px; margin: 0 auto; }
        .category-title { font-size: 22px; color: #8B2E2E; margin-bottom: 6px; font-weight: 700; display: flex; align-items: center; gap: 10px; }
        .category-title::after { content: ""; flex: 1; height: 1px; background: #E8D5A8; }
        .category-desc { font-size: 13px; color: #8B7B6A; margin-bottom: 24px; }

        .menu-list { list-style: none; margin-bottom: 48px; }
        .menu-item { display: flex; justify-content: space-between; align-items: baseline; padding: 12px 0; border-bottom: 1px dashed #E8D5A8; }
        .menu-item:last-child { border-bottom: none; }
        .menu-item-left { flex: 1; }
        .menu-item-left h4 { font-size: 15px; color: #2C2C2C; font-weight: 600; }
        .menu-item-left p { font-size: 12px; color: #8B7B6A; margin-top: 2px; }
        .menu-price { font-size: 16px; color: #C4963C; font-weight: 700; white-space: nowrap; margin-left: 20px; }
        .tag { display: inline-block; background: #8B2E2E; color: #FFF; font-size: 10px; padding: 1px 6px; border-radius: 3px; margin-left: 8px; vertical-align: middle; }

        .menu-note { background: #FFF; border-left: 4px solid #C4963C; padding: 20px 24px; border-radius: 0 6px 6px 0; margin: 40px 0; }
        .menu-note p { font-size: 13px; color: #6B5D4F; }
        .menu-note strong { color: #8B2E2E; }

        .cta { text-align: center; padding: 50px 40px; background: #FFF; }
        .cta h2 { font-size: 24px; color: #3D1F1F; margin-bottom: 12px; }
        .cta p { font-size: 15px; color: #6B5D4F; margin-bottom: 24px; }
        .btn-primary { display: inline-block; background: #8B2E2E; color: #FFF; padding: 13px 40px; border-radius: 4px; font-size: 15px; font-weight: 600; transition: all 0.3s; }
        .btn-primary:hover { background: #6B2222; transform: translateY(-2px); }

