    </footer>

    <script>
        // Set min date to today
        (function() {
            var d = new Date();
            var localISO = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
            document.getElementById('dateInput').setAttribute('min', localISO);
        })();

        function handleSubmit(e) {
            e.preventDefault();
            var form = e.target;
            var phone = form.phone.value;
            var name = form.name.value;
            var date = form.date.value;
            var time = form.time.value;
            var guests = form.guests.value;

            // Simple validation
            if (!name || !phone || !date || !time || !guests) {
                alert('请填写所有必填项（带 * 的字段）。');
                return false;
            }
            if (!/^1[3-9]\d{9}$/.test(phone)) {
                alert('请输入正确的11位手机号码。');
                return false;
            }

            // Show success (no actual submission)
            document.getElementById('successMsg').style.display = 'block';
            form.reset();
            document.getElementById('successMsg').scrollIntoView({ behavior: 'smooth', block: 'center' });
            return false;
        }
    </script>
